CREATE OR REPLACE FUNCTION minicore.fn_update_account_balance()
RETURNS TRIGGER AS $$
DECLARE
    v_code        NUMERIC(5);
    v_amount      NUMERIC(18,2);
    v_sign        SMALLINT;
    v_avail_delta NUMERIC(18,2);
    v_coll_delta  NUMERIC(18,2);
    v_available   NUMERIC(18,2);
    v_collected   NUMERIC(18,2);
BEGIN
    IF NEW.original_transaction_id IS NOT NULL AND NEW.status = 'POSTED' THEN
        SELECT available_balance, collected_balance
        INTO v_available, v_collected
        FROM minicore.accounts
        WHERE account_id = NEW.account_id;
    ELSE
        IF NEW.original_transaction_id IS NOT NULL AND NEW.status = 'CANCELLED' THEN
            SELECT transaction_code, amount
            INTO v_code, v_amount
            FROM minicore.transactions
            WHERE transaction_id = NEW.original_transaction_id;
            v_sign := -1;
        ELSE
            v_code := NEW.transaction_code;
            v_amount := NEW.amount;
            v_sign := 1;
        END IF;
        SELECT
            COALESCE(SUM(CASE WHEN e.balance_name = 'AVAILABLE' THEN v_sign * v_amount * e.effect END), 0),
            COALESCE(SUM(CASE WHEN e.balance_name = 'COLLECTED' THEN v_sign * v_amount * e.effect END), 0)
        INTO v_avail_delta, v_coll_delta
        FROM minicore.transaction_code_balance_effects e
        WHERE e.transaction_code = v_code;
        UPDATE minicore.accounts
        SET available_balance = available_balance + v_avail_delta,
            collected_balance = collected_balance + v_coll_delta,
            updated_at = NOW()
        WHERE account_id = NEW.account_id
        RETURNING available_balance, collected_balance
        INTO v_available, v_collected;
    END IF;
    INSERT INTO minicore.transaction_balances
        (transaction_id, account_id, available_balance, collected_balance)
    VALUES
        (NEW.transaction_id, NEW.account_id, v_available, v_collected);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql
